  public static func createGNP(
    _ fbb: inout FlatBufferBuilder,
    IDOffset ID: Offset,
    NAMEOffset NAME: Offset,
    ASCII_NAMEOffset ASCII_NAME: Offset = Offset(),
    ALTERNATE_NAMESVectorOffset ALTERNATE_NAMES: Offset = Offset(),
    LATITUDE: Double = 0.0,
    LONGITUDE: Double = 0.0,
    ELEVATION_M: Double = 0.0,
    ELEVATION_PUBLISHED: Bool = false,
    DEM_ELEVATION_M: Double = 0.0,
    DEM_MODELOffset DEM_MODEL: Offset = Offset(),
    FEATURE_CLASS: gnpFeatureClass = .unspecified,
    FEATURE_CLASS_CODEOffset FEATURE_CLASS_CODE: Offset = Offset(),
    FEATURE_CODEOffset FEATURE_CODE: Offset = Offset(),
    FEATURE_NAMEOffset FEATURE_NAME: Offset = Offset(),
    COUNTRY_CODEOffset COUNTRY_CODE: Offset = Offset(),
    COUNTRY_NAMEOffset COUNTRY_NAME: Offset = Offset(),
    ALTERNATE_COUNTRY_CODESVectorOffset ALTERNATE_COUNTRY_CODES: Offset = Offset(),
    ADMIN1_CODEOffset ADMIN1_CODE: Offset = Offset(),
    ADMIN1_NAMEOffset ADMIN1_NAME: Offset = Offset(),
    ADMIN2_CODEOffset ADMIN2_CODE: Offset = Offset(),
    ADMIN2_NAMEOffset ADMIN2_NAME: Offset = Offset(),
    ADMIN3_CODEOffset ADMIN3_CODE: Offset = Offset(),
    ADMIN3_NAMEOffset ADMIN3_NAME: Offset = Offset(),
    ADMIN4_CODEOffset ADMIN4_CODE: Offset = Offset(),
    ADMIN4_NAMEOffset ADMIN4_NAME: Offset = Offset(),
    POPULATION: Int64 = 0,
    TIME_ZONE_IDOffset TIME_ZONE_ID: Offset = Offset(),
    TIME_ZONE_UTC_OFFSET_H: Double = 0.0,
    TIME_ZONE_DST_OFFSET_H: Double = 0.0,
    SOURCEOffset SOURCE: Offset
  ) -> Offset {
    let __start = GNP.startGNP(&fbb)
    GNP.add(ID: ID, &fbb)
    GNP.add(NAME: NAME, &fbb)
    GNP.add(ASCII_NAME: ASCII_NAME, &fbb)
    GNP.addVectorOf(ALTERNATE_NAMES: ALTERNATE_NAMES, &fbb)
    GNP.add(LATITUDE: LATITUDE, &fbb)
    GNP.add(LONGITUDE: LONGITUDE, &fbb)
    GNP.add(ELEVATION_M: ELEVATION_M, &fbb)
    GNP.add(ELEVATION_PUBLISHED: ELEVATION_PUBLISHED, &fbb)
    GNP.add(DEM_ELEVATION_M: DEM_ELEVATION_M, &fbb)
    GNP.add(DEM_MODEL: DEM_MODEL, &fbb)
    GNP.add(FEATURE_CLASS: FEATURE_CLASS, &fbb)
    GNP.add(FEATURE_CLASS_CODE: FEATURE_CLASS_CODE, &fbb)
    GNP.add(FEATURE_CODE: FEATURE_CODE, &fbb)
    GNP.add(FEATURE_NAME: FEATURE_NAME, &fbb)
    GNP.add(COUNTRY_CODE: COUNTRY_CODE, &fbb)
    GNP.add(COUNTRY_NAME: COUNTRY_NAME, &fbb)
    GNP.addVectorOf(ALTERNATE_COUNTRY_CODES: ALTERNATE_COUNTRY_CODES, &fbb)
    GNP.add(ADMIN1_CODE: ADMIN1_CODE, &fbb)
    GNP.add(ADMIN1_NAME: ADMIN1_NAME, &fbb)
    GNP.add(ADMIN2_CODE: ADMIN2_CODE, &fbb)
    GNP.add(ADMIN2_NAME: ADMIN2_NAME, &fbb)
    GNP.add(ADMIN3_CODE: ADMIN3_CODE, &fbb)
    GNP.add(ADMIN3_NAME: ADMIN3_NAME, &fbb)
    GNP.add(ADMIN4_CODE: ADMIN4_CODE, &fbb)
    GNP.add(ADMIN4_NAME: ADMIN4_NAME, &fbb)
    GNP.add(POPULATION: POPULATION, &fbb)
    GNP.add(TIME_ZONE_ID: TIME_ZONE_ID, &fbb)
    GNP.add(TIME_ZONE_UTC_OFFSET_H: TIME_ZONE_UTC_OFFSET_H, &fbb)
    GNP.add(TIME_ZONE_DST_OFFSET_H: TIME_ZONE_DST_OFFSET_H, &fbb)
    GNP.add(SOURCE: SOURCE, &fbb)
    return GNP.endGNP(&fbb, start: __start)
  }

  public static func verify<T>(_ verifier: inout Verifier, at position: Int, of type: T.Type) throws where T: Verifiable {
    var _v = try verifier.visitTable(at: position)
    try _v.visit(field: VT.ID, fieldName: "ID", required: true, type: ForwardOffset<String>.self)
    try _v.visit(field: VT.NAME, fieldName: "NAME", required: true, type: ForwardOffset<String>.self)
    try _v.visit(field: VT.ASCII_NAME, fieldName: "ASCII_NAME", required: false, type: ForwardOffset<String>.self)
    try _v.visit(field: VT.ALTERNATE_NAMES, fieldName: "ALTERNATE_NAMES", required: false, type: ForwardOffset<Vector<ForwardOffset<GNPName>, GNPName>>.self)
    try _v.visit(field: VT.LATITUDE, fieldName: "LATITUDE", required: false, type: Double.self)
    try _v.visit(field: VT.LONGITUDE, fieldName: "LONGITUDE", required: false, type: Double.self)
    try _v.visit(field: VT.ELEVATION_M, fieldName: "ELEVATION_M", required: false, type: Double.self)
    try _v.visit(field: VT.ELEVATION_PUBLISHED, fieldName: "ELEVATION_PUBLISHED", required: false, type: Bool.self)
    try _v.visit(field: VT.DEM_ELEVATION_M, fieldName: "DEM_ELEVATION_M", required: false, type: Double.self)
    try _v.visit(field: VT.DEM_MODEL, fieldName: "DEM_MODEL", required: false, type: ForwardOffset<String>.self)
    try _v.visit(field: VT.FEATURE_CLASS, fieldName: "FEATURE_CLASS", required: false, type: gnpFeatureClass.self)
    try _v.visit(field: VT.FEATURE_CLASS_CODE, fieldName: "FEATURE_CLASS_CODE", required: false, type: ForwardOffset<String>.self)
    try _v.visit(field: VT.FEATURE_CODE, fieldName: "FEATURE_CODE", required: false, type: ForwardOffset<String>.self)
    try _v.visit(field: VT.FEATURE_NAME, fieldName: "FEATURE_NAME", required: false, type: ForwardOffset<String>.self)
    try _v.visit(field: VT.COUNTRY_CODE, fieldName: "COUNTRY_CODE", required: false, type: ForwardOffset<String>.self)
    try _v.visit(field: VT.COUNTRY_NAME, fieldName: "COUNTRY_NAME", required: false, type: ForwardOffset<String>.self)
    try _v.visit(field: VT.ALTERNATE_COUNTRY_CODES, fieldName: "ALTERNATE_COUNTRY_CODES", required: false, type: ForwardOffset<Vector<ForwardOffset<String>, String>>.self)
    try _v.visit(field: VT.ADMIN1_CODE, fieldName: "ADMIN1_CODE", required: false, type: ForwardOffset<String>.self)
    try _v.visit(field: VT.ADMIN1_NAME, fieldName: "ADMIN1_NAME", required: false, type: ForwardOffset<String>.self)
    try _v.visit(field: VT.ADMIN2_CODE, fieldName: "ADMIN2_CODE", required: false, type: ForwardOffset<String>.self)
    try _v.visit(field: VT.ADMIN2_NAME, fieldName: "ADMIN2_NAME", required: false, type: ForwardOffset<String>.self)
    try _v.visit(field: VT.ADMIN3_CODE, fieldName: "ADMIN3_CODE", required: false, type: ForwardOffset<String>.self)
    try _v.visit(field: VT.ADMIN3_NAME, fieldName: "ADMIN3_NAME", required: false, type: ForwardOffset<String>.self)
    try _v.visit(field: VT.ADMIN4_CODE, fieldName: "ADMIN4_CODE", required: false, type: ForwardOffset<String>.self)
    try _v.visit(field: VT.ADMIN4_NAME, fieldName: "ADMIN4_NAME", required: false, type: ForwardOffset<String>.self)
    try _v.visit(field: VT.POPULATION, fieldName: "POPULATION", required: false, type: Int64.self)
    try _v.visit(field: VT.TIME_ZONE_ID, fieldName: "TIME_ZONE_ID", required: false, type: ForwardOffset<String>.self)
    try _v.visit(field: VT.TIME_ZONE_UTC_OFFSET_H, fieldName: "TIME_ZONE_UTC_OFFSET_H", required: false, type: Double.self)
    try _v.visit(field: VT.TIME_ZONE_DST_OFFSET_H, fieldName: "TIME_ZONE_DST_OFFSET_H", required: false, type: Double.self)
    try _v.visit(field: VT.SOURCE, fieldName: "SOURCE", required: true, type: ForwardOffset<GNPProvenance>.self)
    _v.finish()
  }
